  "prompt": "prompts/physics_committee_luna_round1_v1.md",
  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B014",
        "laureates": [
          "Kenneth J. Schafer",
          "Maciej Lewenstein",
          "Paul B. Corkum"
        ],
        "citation": "For the electron recollision model and its quantum theory of high-harmonic generation."
      }
    ]
  },
  "alternatives": [
    "B043",
    "B002"
  ],
  "statement": {
    "case_for": "The recollision picture explained how an electron driven by a strong laser field can return to its parent ion and emit high-harmonic radiation. Together with its quantum formulation, this gave a quantitative framework that could be tested across experiments and opened a way to study electron motion on its natural timescale. Its value is a fundamental account of an unexpected process, not just a route to shorter pulses.",
    "case_against": "The boundary between the original model, its quantum formulation, and later experimental advances is not sharp. The proposed trio may leave out important contributors, and the subject overlaps with the attosecond science recognized in 2023. A citation must identify the specific theoretical and physical contribution clearly enough to avoid treating the whole field as one discovery.",
    "responses": [
      {
        "member_id": "olsson-eva",
        "point": "Olsson notes that the candidate overlaps conceptually with the 2023 attosecond prize and that the discovery boundary needs careful definition.",
        "response": "That overlap is real and should shape the citation, but it does not erase the distinction between recognizing attosecond experimental advances and recognizing the recollision mechanism and its quantum theory. The proposed citation should stay narrowly with high-harmonic generation's physical explanation."
      },
      {
        "member_id": "johansson-goran",
        "point": "Johansson argues that the theoretical framing may underrepresent the experiments that established and extended high-harmonic generation.",
        "response": "I agree that experiments were essential tests and that the field is broader than these three names. The case here is for a sharply bounded theoretical contribution: Corkum's recollision picture and the complementary quantitative work of Lewenstein and Schafer. That scope should not imply that theory alone built attosecond science."
      }
    ],
    "uncertainties": [
      "The historical division of credit among the recollision model, the quantum formulation, and experimental demonstrations needs further scrutiny.",
      "The distinction between this contribution and the attosecond work recognized in 2023 should be made explicit in any final citation."
    ],
    "conflict_note": "I have a long-standing close collaboration with Anne L'Huillier, whose work is adjacent to this field; she is not among the proposed laureates. No connection to the proposed laureates is apparent from my supplied profile."
  }
}
